<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),orders=ref<any[]>([]),visible=ref(false),selected=ref<any>(),orderId=ref<number>();async function load(){try{[rows.value,orders.value]=await Promise.all([api.exceptions(),api.orders()])as any}catch(e:any){ElMessage.error(e.message)}}function open(row:any){selected.value=row;orderId.value=undefined;visible.value=true}async function match(){if(!orderId.value)return ElMessage.warning('请选择订单');try{await api.manualMatch(selected.value.id,orderId.value);ElMessage.success('人工匹配完成');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>异常匹配</h1><p>未匹配或多匹配的数据必须由客服人工确认，不自动覆盖订单。</p></div></div><div class="table-card"><el-table :data="rows"><el-table-column prop="rowNumber" label="文件行" width="80"/><el-table-column prop="umallOrderNo" label="UMALL订单号" min-width="150"/><el-table-column prop="iccid" label="ICCID" min-width="180"/><el-table-column prop="phone" label="手机号" min-width="130"/><el-table-column prop="planName" label="套餐" min-width="160"/><el-table-column prop="matchStatus" label="异常类型" width="120"/><el-table-column prop="exceptionReason" label="异常原因" min-width="240"/><el-table-column label="操作" fixed="right" width="110"><template #default="s"><el-button link type="primary" @click="open(s.row)">人工匹配</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="人工确认订单" width="600"><div class="hint-box" style="margin-bottom:18px">选择后只建立匹配关系；若批次已经确认，会同步更新对应订单。</div><el-select v-model="orderId" filterable placeholder="按订单号或手机号选择" style="width:100%"><el-option v-for="o in orders" :key="o.id" :label="`${o.orderNo} · ${o.contactPhone} · ${o.planName}`" :value="o.id"/></el-select><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="match">确认匹配</el-button></div></template></el-dialog></div></template>

